import { Children } from "react"
import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"

type BoardProps = {
  /** <BoardColumn /> elements, one per pipeline stage. */
  children: React.ReactNode
  label?: string
  className?: string
}

/**
 * Figma `Board`: stage columns side by side with 12px gaps. Wide screens fit 5 columns
 * (min 200px); narrower ones scroll horizontally with snap, one column ≈ 85% of the screen on phones.
 */
export function Board({ children, label = "Этапы", className }: BoardProps) {
  return (
    <ul
      aria-label={label}
      data-slot="board"
      className={cn(
        "grid snap-x snap-mandatory auto-cols-[minmax(260px,85%)] grid-flow-col gap-3 overflow-x-auto pb-2",
        "md:auto-cols-[minmax(240px,1fr)] xl:auto-cols-[minmax(200px,1fr)]",
        className,
      )}
    >
      {Children.map(children, (column) => (
        <li className="min-w-0 snap-start">{column}</li>
      ))}
    </ul>
  )
}

import { Children, useId } from "react"
import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { Badge } from "@/registry/mbank/ui/badge"

type BoardColumnProps = {
  title: string
  /** Total in the stage (the badge), may be larger than the cards shown. */
  count: number
  /** Line under the title: "SLA этапа 15 мин". */
  sla?: string
  /** <ApplicationCard /> elements. */
  children?: React.ReactNode
  /** <ShowMore /> under the cards. */
  footer?: React.ReactNode
  emptyText?: string
  className?: string
}

/** Figma `Column <stage>`: header 48 (name 16 bold + count badge, SLA caption), cards 8px apart. */
export function BoardColumn({ title, count, sla, children, footer, emptyText = "Нет заявок", className }: BoardColumnProps) {
  const titleId = useId()
  const cards = Children.toArray(children)
  return (
    <section aria-labelledby={titleId} data-slot="board-column" className={cn("flex flex-col gap-2", className)}>
      <header className="flex h-12 flex-col gap-1">
        <div className="flex items-center gap-2">
          <h3 id={titleId} className="truncate text-base font-bold text-foreground">
            {title}
          </h3>
          <Badge size="sm" tone="neutral" aria-label={`${count} заявок`}>
            {count}
          </Badge>
        </div>
        {sla && <p className="truncate text-caption text-muted-foreground">{sla}</p>}
      </header>
      {cards.length > 0 ? (
        <ul className="flex flex-col gap-2">
          {cards.map((card, index) => (
            <li key={index}>{card}</li>
          ))}
        </ul>
      ) : (
        <p className="rounded-md border border-dashed border-border-secondary px-3 py-6 text-center text-sm text-muted-foreground">
          {emptyText}
        </p>
      )}
      {footer}
    </section>
  )
}

import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { Badge } from "@/registry/mbank/ui/badge"

type BadgeTone = React.ComponentProps<typeof Badge>["tone"]

type CardLinkProps = { href: string; className: string; children: React.ReactNode; "data-slot": string }

type ApplicationCardProps = {
  /** "CL-240131". */
  id: string
  /** Already formatted: "10:41". */
  time: string
  /** Borrower name. */
  title: string
  /** Already formatted: "120 000 KGS". */
  amount: string
  /** "Потребительский · 12 мес". */
  meta?: string
  /** SLA or status badge: { label: "SLA 12 мин", tone: "info" }. */
  status?: { label: string; tone: BadgeTone }
  href: string
  /** Router link (default: <a href>). Spread the props: data-slot is part of the contract. */
  renderLink?: (props: CardLinkProps) => React.ReactNode
  className?: string
}

const anchor = ({ href, ...props }: CardLinkProps) => <a href={href} {...props} />

/**
 * Figma `CRM / Application card` (contract crm-application-card): p 12, gap 4, radius-md, card surface;
 * id + time caption, name body/s medium, amount body/l bold, meta caption, footer pt 4 with Badge-status S rounded.
 */
export function ApplicationCard({
  id,
  time,
  title,
  amount,
  meta,
  status,
  href,
  renderLink = anchor,
  className,
}: ApplicationCardProps) {
  return renderLink({
    href,
    "data-slot": "application-card",
    className: cn(
      "flex flex-col gap-1 rounded-md bg-card p-3 text-card-foreground transition-shadow outline-none",
      "hover:shadow-sm focus-visible:ring-[3px] focus-visible:ring-ring/30",
      className,
    ),
    children: (
      <>
        <span data-slot="application-card-top" className="flex items-center justify-between gap-2 text-caption text-muted-foreground">
          <span data-slot="application-card-id">{id}</span>
          <span data-slot="application-card-time">{time}</span>
        </span>
        <span data-slot="application-card-name" className="truncate text-sm font-medium text-foreground">
          {title}
        </span>
        <span data-slot="application-card-amount" className="text-base font-bold text-foreground">
          {amount}
        </span>
        {meta && (
          <span data-slot="application-card-meta" className="truncate text-caption text-muted-foreground">
            {meta}
          </span>
        )}
        {status && (
          <span data-slot="application-card-footer" className="flex pt-1">
            <Badge data-slot="application-card-badge" size="sm" tone={status.tone}>
              {status.label}
            </Badge>
          </span>
        )}
      </>
    ),
  })
}

import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { Button } from "@/registry/mbank/ui/button"

type ShowMoreProps = Omit<React.ComponentProps<typeof Button>, "children" | "variant"> & {
  /** How many are hidden: renders "Показать ещё {count}". */
  count: number
  label?: (count: number) => string
}

/** Figma `Show more` under a board column: link-style 28px button. */
export function ShowMore({ count, label = (n) => `Показать ещё ${n}`, className, ...props }: ShowMoreProps) {
  if (count <= 0) return null
  return (
    <Button
      variant="link"
      size="xs"
      data-slot="show-more"
      className={cn("h-7 w-fit px-2 text-sm font-normal", className)}
      {...props}
    >
      {label(count)}
    </Button>
  )
}

import { Skeleton } from "@/registry/mbank/ui/skeleton"

type BoardSkeletonProps = { columns?: number; cards?: number; label?: string }

/** Loading state of <Board />: the same column grid with card-sized placeholders. */
export function BoardSkeleton({ columns = 5, cards = 3, label = "Загружаем заявки" }: BoardSkeletonProps) {
  return (
    <div
      role="status"
      aria-label={label}
      data-slot="board-skeleton"
      className="grid auto-cols-[minmax(260px,85%)] grid-flow-col gap-3 overflow-hidden md:auto-cols-[minmax(240px,1fr)] xl:auto-cols-[minmax(200px,1fr)]"
    >
      {Array.from({ length: columns }, (_, column) => (
        <div key={column} className="flex flex-col gap-2">
          <Skeleton className="h-6 w-28" />
          <Skeleton className="mb-1 h-4 w-20" />
          {Array.from({ length: cards }, (_, card) => (
            <Skeleton key={card} className="h-35 rounded-md bg-surface-0" />
          ))}
        </div>
      ))}
    </div>
  )
}
